package br.com.petshop.controller; import org.springframework.http.*; import org.springframework.web.bind.annotation.*; import java.util.*; @RestControllerAdvice(basePackages="br.com.petshop.controller") public class ExceptionHandlerController { @ExceptionHandler({IllegalArgumentException.class,NoSuchElementException.class}) ResponseEntity<Map<String,String>> handle(RuntimeException e){return ResponseEntity.badRequest().body(Map.of("erro",e.getMessage()));} }
